-- In-app messages: the dialog that pops up for users (and opens from the me
-- screen's "Visszajelzés" menu), edited from the admin instead of
-- shipped in the app.
--
-- Append-only: the app shows the newest row, and the admin's "Mentés" inserts
-- a new one rather than updating, so every past version stays in the table.
-- A row the user has not seen yet pops up on its own (see
-- components/InAppMessageDialog.tsx), which is why it is also on realtime.

CREATE TABLE IF NOT EXISTS "public"."in_app_messages" (
    "id"              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "created_at"      timestamp with time zone NOT NULL DEFAULT "now"(),
    "icon"            "text",
    "open_icon"       "text",
    "title"           "text" NOT NULL,
    "body"            "text" NOT NULL,
    "primary_label"   "text",
    "primary_url"     "text",
    "secondary_label" "text",
    "secondary_url"   "text"
);

ALTER TABLE "public"."in_app_messages" OWNER TO "postgres";

COMMENT ON TABLE  "public"."in_app_messages"        IS 'Content of the in-app message dialog. The newest row is shown; a new row is shown automatically to everyone who has not seen it yet.';
COMMENT ON COLUMN "public"."in_app_messages"."icon" IS 'An http(s) image URL, or a MaterialCommunityIcons name. NULL = no icon.';
COMMENT ON COLUMN "public"."in_app_messages"."open_icon" IS 'MaterialCommunityIcons name of the header menu item that opens the dialog. NULL = the app default (message-draw).';
COMMENT ON COLUMN "public"."in_app_messages"."body" IS 'Plain text. Links: [label](url) or a bare https:// URL. url may be an in-app path ("/chat/<uid>"), https:, mailto: or tel:.';
COMMENT ON COLUMN "public"."in_app_messages"."primary_url"   IS 'In-app path ("/chat/<uid>") or an external / mailto: URL. A button needs both label and url to show.';
COMMENT ON COLUMN "public"."in_app_messages"."secondary_url" IS 'Same as primary_url.';

-- Members read; only service_role (the admin's Netlify function) writes.
ALTER TABLE "public"."in_app_messages" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "in_app_messages_select_authenticated"
  ON "public"."in_app_messages"
  FOR SELECT TO authenticated
  USING (true);

REVOKE ALL ON "public"."in_app_messages" FROM anon, authenticated;
GRANT SELECT ON "public"."in_app_messages" TO authenticated;
GRANT ALL ON "public"."in_app_messages" TO service_role;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.in_app_messages;
  END IF;
END;
$$;

